def describe_civilization_layer_intelligence() -> str:
    lines = [
        "TitanAI Advanced Intelligence Civilization Layer",
        "",
        "This layer frames TitanAI as an intelligence ecosystem spanning coordination, enterprise creation, software factories, product evolution, security, knowledge civilizations, research, economics, logistics, personal intelligence, commerce, developer workspaces, monitoring, communication, governance, and human-AI partnership.",
        "",
    ]
    for capability in CIVILIZATION_LAYER_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
